// Package ts carries the TypeScript SDK's files (@kario/sdk) for the kario
// command, which copies them into the projects it creates, bundles KarioUI
// and the test library into apps and tests, and runs apps under Node.js.
package ts

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	capi "github.com/kario-os/kario/sdk/c/include"
)

// Files: index.d.ts (the module "kario"), ui.d.ts (generated by tools/tsgen)
// and package.json; karioui/ (@kario/ui) and kariotest/ (@kario/test), the
// TypeScript sources bundled into apps and their tests; node/, the module
// "kario" for Node.js (kario run, kario test), with native.c, the addon
// that loads native modules there, and web.js, the web's Blob, FormData,
// Headers, Request and Response, which kario-jsrt compiles in too.
//
//go:embed index.d.ts ui.d.ts package.json karioui/index.ts kariotest/index.ts node/*.mjs node/web.js node/native.c
var Files embed.FS

// Modules are the SDK's TypeScript libraries by import name.
var Modules = map[string]string{
	"@kario/ui":   "karioui/index.ts",
	"@kario/test": "kariotest/index.ts",
}

// Source is a library's TypeScript source by its import name.
func Source(module string) ([]byte, error) {
	f, ok := Modules[module]
	if !ok {
		return nil, fmt.Errorf("no module %q in the SDK", module)
	}
	return Files.ReadFile(f)
}

// Node is the runtime for Node.js (node/), its files by name.
func Node() (map[string][]byte, error) {
	out := map[string][]byte{}
	entries, err := fs.ReadDir(Files, "node")
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		raw, err := Files.ReadFile("node/" + e.Name())
		if err != nil {
			return nil, err
		}
		out[e.Name()] = raw
	}
	return out, nil
}

// Addon is the file native.mjs loads native modules through.
const Addon = "kario-native.node"

// BuildAddon compiles node/native.c into dir/kario-native.node with the C
// compiler cc, for an app with native modules under Node.js; a build of
// the same sources by the same compiler is kept.
func BuildAddon(dir, cc string) error {
	src, err := Files.ReadFile("node/native.c")
	if err != nil {
		return err
	}
	sum := sha256.Sum256([]byte(cc + "\x00" + string(src) + "\x00" + string(capi.NativeHeader)))
	stamp, out := filepath.Join(dir, Addon+".sum"), filepath.Join(dir, Addon)
	if old, err := os.ReadFile(stamp); err == nil && string(old) == hex.EncodeToString(sum[:]) {
		if _, err := os.Stat(out); err == nil {
			return nil
		}
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	for name, raw := range map[string][]byte{"native.c": src, "kario_native.h": capi.NativeHeader} {
		if err := os.WriteFile(filepath.Join(dir, name), raw, 0o644); err != nil {
			return err
		}
	}
	tmp := out + ".tmp"
	cmd := exec.Command(cc, "-shared", "-fPIC", "-O2", "-pthread", "-I"+dir, "-o", tmp, filepath.Join(dir, "native.c"), "-ldl")
	if msg, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("%s: %v: %s", strings.Join(cmd.Args, " "), err, strings.TrimSpace(string(msg)))
	}
	if err := os.Rename(tmp, out); err != nil {
		return err
	}
	return os.WriteFile(stamp, []byte(hex.EncodeToString(sum[:])), 0o644)
}
